  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
