/**
 * A member's out-of-office window. Away from `startsAt` (inclusive) up to
 * `endsAt` (exclusive); while away, work meant for them goes to `delegateUserId`.
 */
export interface MemberAbsence extends TenantScoped {
  readonly userId: UserId;
  readonly delegateUserId: UserId | null;
  readonly startsAt: IsoTimestamp;
  readonly endsAt: IsoTimestamp;
  readonly note: string | null;
}

/** True when `at` falls inside the absence window: start inclusive, end exclusive. */
export function isAwayAt(
  absence: Pick<MemberAbsence, "startsAt" | "endsAt">,
  at: Date,
): boolean {
