import { hasRoleAtLeast, isAwayAt } from "@/types/member";
import {
  actorEnvelope,
  memberResource,
  NotFoundError,
  orgResource,
  requireFound,
} from "./_support";
import type {
  ListMembersInput,
  RemoveMemberInput,
  SetAbsenceInput,
  UpdateMemberRoleInput,
} from "@/schemas/member";
import type { MemberId, OrgId, Page, UserId } from "@/types/common";
import type {
  Actor,
  Member,
  MemberAbsence,
  MemberWithUser,
  Role,
} from "@/types/member";

/** How many members are scanned when counting the remaining owners. */
const OWNER_SCAN_LIMIT = 100;

/**
 * Sets (or replaces) a member's absence. Only someone who may change roles can
 * set another member's absence; everyone else may set only their own. The
 * window is start-inclusive and end-exclusive, and the delegate must be another
 * active member of the same workspace.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanManageAbsence(actor, member);

  if (Date.parse(input.endsAt) <= Date.parse(input.startsAt)) {
    throw new Error("An absence must end after it starts");
  }

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId: input.delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note,
  });
}

/** Clearing is idempotent: clearing a member with no absence succeeds. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCanManageAbsence(actor, member);

  await memberRepo.deleteAbsence(orgId, userId);
}

/**
 * The member's stored absence while it has not yet ended — including one that
 * is scheduled but not started — or `null` once it has ended or none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", orgResource(orgId));

  await requireActiveMember(orgId, userId);

  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null) return null;
  return Date.now() < Date.parse(absence.endsAt) ? absence : null;
}

/**
 * The delegate who takes over `userId`'s work at `at`, or `null` when the
 * member is not away then or has no delegate. Shared by the assignment path,
 * the overdue alerts and the mention alerts so "away" is decided one way.
 */
export async function delegateWhileAway(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return null;
  return isAwayAt(absence, at) ? absence.delegateUserId : null;
}

/**
 * Who an assignment to `assigneeId` actually lands on. Taking an issue yourself
 * is never redirected; otherwise an away assignee's delegate takes it. The
 * delegate is used as-is — delegation is not chained through a second absence.
 */
export async function resolveAssignee(
  actor: Actor,
  assigneeId: UserId | null,
  at: Date,
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === actor.userId) return assigneeId;
  return (await delegateWhileAway(actor.orgId, assigneeId, at)) ?? assigneeId;
}

async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

function assertCanManageAbsence(actor: Actor, member: Member): void {
  if (actor.userId === member.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

