/**
 * Each mentioned user plus, for those away at `at`, their delegate. A Set keeps
 * a delegate who is also mentioned directly down to one alert.
 */
async function withDelegates(
  orgId: OrgId,
  userIds: readonly UserId[],
  at: Date,
): Promise<readonly UserId[]> {
  const recipients = new Set<UserId>(userIds);
  for (const userId of userIds) {
    const delegate = await delegateWhileAway(orgId, userId, at);
    if (delegate !== null) recipients.add(delegate);
  }
  return [...recipients];
}

