import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IsoTimestamp, UserId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
const PAST = "2020-01-01T00:00:00.000Z" as IsoTimestamp;
const FUTURE_START = "2999-01-01T00:00:00.000Z" as IsoTimestamp;
const FUTURE_END = "2999-02-01T00:00:00.000Z" as IsoTimestamp;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("absence-scratch", "growth");
});
afterAll(() => cleanup());

describe("absence scratch", () => {
  it("round-trips, validates, and redirects assignments and mentions", async () => {
    const { owner, admin, member, viewer } = tenant.userIds;
    const o = tenant.org.id;

    const stored = await memberService.setAbsence(tenant.actors.member, {
      orgId: o, userId: viewer, delegateUserId: admin, startsAt: PAST, endsAt: FUTURE_END, note: "trip",
    });
    expect(stored).toMatchObject({ userId: viewer, delegateUserId: admin, note: "trip" });
    expect(await memberService.getAbsence(tenant.actors.admin, o, viewer)).not.toBeNull();

    await expect(memberService.setAbsence(tenant.actors.member, {
      orgId: o, userId: member, delegateUserId: null, startsAt: FUTURE_END, endsAt: FUTURE_START, note: null,
    })).rejects.toThrow();
    await expect(memberService.setAbsence(tenant.actors.member, {
      orgId: o, userId: member, delegateUserId: member, startsAt: PAST, endsAt: FUTURE_END, note: null,
    })).rejects.toThrow(/own delegate/);
    await expect(memberService.setAbsence(tenant.actors.member, {
      orgId: o, userId: admin, delegateUserId: null, startsAt: PAST, endsAt: FUTURE_END, note: null,
    })).rejects.toThrow();

    // Viewer assigns issue to member (away? no) -> then viewer's issue assignment redirects.
    const issue = await issueService.createIssue(tenant.actors.owner, issueInput(o, tenant.project.id, { title: "Away redirect", assigneeId: viewer }));
    expect(issue.assigneeId).toBe(admin);

    // Self-take is not redirected.
    const own = await issueService.createIssue(tenant.actors.viewer, issueInput(o, tenant.project.id, { title: "Take it myself", assigneeId: viewer }));
    expect(own.assigneeId).toBe(viewer);

    // Not yet started: no redirect.
    await memberService.setAbsence(tenant.actors.owner, {
      orgId: o, userId: member, delegateUserId: admin, startsAt: FUTURE_START, endsAt: FUTURE_END, note: null,
    });
    const notYet = await issueService.createIssue(tenant.actors.owner, issueInput(o, tenant.project.id, { title: "Not yet away", assigneeId: member }));
    expect(notYet.assigneeId).toBe(member);

    // Mention alerts viewer and delegate admin once each.
    await emit("comment.created", {
      orgId: o, actorId: owner, occurredAt: issue.createdAt, commentId: "cmt-x" as CommentId,
      issueId: issue.id, mentionedUserIds: [viewer, admin],
    });
    const forAdmin = await listNotifications(tenant.actors.owner, { orgId: o, recipientId: admin, unreadOnly: false, kind: ["comment_mention"], limit: 25, cursor: null });
    expect(forAdmin.items).toHaveLength(1);

    // Removing delegate drops delegation: absence stays, delegate null.
    await memberService.removeMember(tenant.actors.owner, {
      orgId: o, memberId: (await memberRepo.findMember(o, admin))!.id,
    });
    const after = await memberRepo.findAbsence(o, viewer);
    expect(after?.delegateUserId).toBeNull();
    expect(after).not.toBeNull();

    await memberService.clearAbsence(tenant.actors.member, o, viewer).catch(() => undefined);
    await memberService.clearAbsence(tenant.actors.viewer, o, viewer);
    expect(await memberRepo.findAbsence(o, viewer)).toBeNull();
    expect(await memberService.getAbsence(tenant.actors.viewer, o, viewer)).toBeNull();
    void (undefined as UserId | undefined);
  });
});
